page.css:
*{margin:0;padding:0;box-sizing:border-box}
:root{--ink:#070a0e;--red:#e4121b;--red-l:#ff3b43;--red-d:#a90d14;--tx2:#a9b9c3;--fd:'Archivo',system-ui,sans-serif;--fb:'Inter',system-ui,sans-serif;--gut:clamp(18px,5vw,56px)}
body{font-family:var(--fb);background:radial-gradient(120% 120% at 50% -10%,#141d26,var(--ink) 62%);color:#eaf2f6;min-height:100vh;display:grid;place-items:center;padding:var(--gut);line-height:1.6;overflow-x:hidden}
svg{width:18px;height:18px;flex-shrink:0}
a{color:inherit;text-decoration:none}
.card{max-width:620px;text-align:center;animation:up .7s both}
@keyframes up{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
.tick{width:92px;height:92px;border-radius:50%;background:rgba(228,18,27,.14);border:1px solid rgba(228,18,27,.42);display:grid;place-items:center;margin:0 auto 28px;animation:pulse 2.4s ease-in-out infinite}
@keyframes pulse{0%,100%{box-shadow:0 0 0 0 rgba(228,18,27,.42)}70%{box-shadow:0 0 0 20px rgba(228,18,27,0)}}
.tick svg{width:42px;height:42px;color:var(--red-l)}
h1{font-family:var(--fd);font-weight:800;font-size:clamp(28px,5vw,44px);text-transform:uppercase;line-height:1.02;letter-spacing:-.015em}
p{color:var(--tx2);margin-top:16px;font-size:16.5px}
.btns{display:flex;gap:14px;justify-content:center;flex-wrap:wrap;margin-top:32px}
.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;border-radius:10px;padding:16px 28px;font-size:15px;text-transform:uppercase;letter-spacing:.03em;transition:.2s}
.btn-r{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;box-shadow:0 16px 32px -12px rgba(228,18,27,.75)}
.btn-gh{background:rgba(255,255,255,.07);color:#fff;border:1.5px solid rgba(255,255,255,.3)}
.btn:hover{transform:translateY(-3px)}
.fine{margin-top:30px;font-size:13.5px;color:#7d8e9b}
@media (prefers-reduced-motion:reduce){.card,.tick{animation:none}}
